// Auth + normalize (hybrid contract) into Event Schema v1.
// NOTE: This is a minimal, import-safe implementation. Customize in dev n8n UI and export via ops/scripts/n8n_gitops_webhooks.py.

const headers = ($json.headers || $json.header || $json) || {};
const auth = headers.authorization || headers.Authorization;

if (!auth || !String(auth).startsWith('Bearer ')) {
  const err = new Error('Unauthorized: missing Authorization: Bearer <token>');
  err.statusCode = 401;
  throw err;
}

const body = ($json.body && typeof $json.body === 'object') ? $json.body : $json;
const query = ($json.query && typeof $json.query === 'object') ? $json.query : {};

function nowIso() { return new Date().toISOString(); }
function makeCorrelationId() { return `corr-${Date.now()}-${Math.random().toString(16).slice(2)}`; }

function looksLikeEventV1(b) {
  return b && typeof b === 'object' && typeof b.type === 'string' && typeof b.source === 'string' && typeof b.env === 'string' && typeof b.timestamp === 'string' && b.payload && typeof b.payload === 'object';
}

let event;
if (looksLikeEventV1(body)) {
  event = { ...body };
} else {
  const type = String(body.event_type ?? query.event_type ?? body.event ?? query.event ?? '').trim();
  const meta = body.meta ?? body.metadata ?? undefined;
  const payload = body.payload ?? body.data ?? {};

  event = {
    id: String(body.id ?? `${Date.now()}`),
    type,
    source: String(body.source ?? meta?.source ?? 'external'),
    env: String(body.env ?? meta?.env ?? 'prod'),
    timestamp: String(body.timestamp ?? meta?.timestamp ?? nowIso()),
    correlation_id: String(body.correlation_id ?? meta?.correlation_id ?? makeCorrelationId()),
    payload: (payload && typeof payload === 'object') ? payload : {},
    meta,
  };
}

return [{ json: event }];

// Validate registry result + required_payload_fields against event.payload.

const event = $json;
const rows = $input.all().map(i => i.json);

// In n8n Postgres node, results are typically output as items where json is each row.
// We expect to be running this node with the Postgres node output, so $json is a registry row.
// To keep import-safe, handle both shapes.

const registry = $json && $json.event_type ? $json : (rows[0] && rows[0].event_type ? rows[0] : null);

if (!registry) {
  const err = new Error(`Unknown or inactive event type: ${event.type}`);
  err.statusCode = 404;
  throw err;
}

const required = Array.isArray(registry.required_payload_fields)
  ? registry.required_payload_fields
  : (typeof registry.required_payload_fields === 'string' ? JSON.parse(registry.required_payload_fields) : []);

function getPath(obj, path) {
  return String(path).split('.').reduce((acc, k) => (acc && typeof acc === 'object' ? acc[k] : undefined), obj);
}

const missing = [];
for (const p of required) {
  const v = getPath(event.payload, p);
  if (v === undefined || v === null || v === '') missing.push(String(p));
}

if (missing.length) {
  const err = new Error(`Missing required payload fields: ${missing.join(', ')}`);
  err.statusCode = 400;
  throw err;
}

// Merge event + registry for downstream routing.
return [{ json: { ...event, registry } }];
